  c.strokeStyle = "#3a2416"; c.lineWidth = 1.4; c.beginPath(); const h1 = f.pt(-23, -26); c.moveTo(h1.x, h1.y); const hc = f.pt(-17, -40), h2 = f.pt(-11, -26); c.quadraticCurveTo(hc.x, hc.y, h2.x, h2.y); c.stroke();
