  for (let i = 0; i < 1500; i++) {
    const t = Math.pow(p.r(), 1.7), y = horizon + t * (ART_H - horizon), x = rnd(p, -10, 610), len = 2 + t * 26 * p.r();
    const lit = p.r() < 0.55;
