for (let i = 0; i < 260; i++) {
  const a = rnd(p, 0, TAU), rr = Math.sqrt(p.r());
  const px = cx + Math.cos(a) * rr * rx, py = cy + Math.sin(a) * rr * ry;
  const facing = ((px - cx) * dx + (py - cy) * dy) / (d * rx);
  if (facing < 0.2) continue;
